const input = $input.first().json;

// O AI Agent pode retornar em campos diferentes dependendo da configuração
let raw =
  input.output ??
  input.text ??
  input.response ??
  input.message ??
  input.result ??
  input;

// Se vier como string, limpar markdown e converter em JSON
let data;

if (typeof raw === 'string') {
  raw = raw
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  try {
    data = JSON.parse(raw);
  } catch (error) {
    throw new Error(`Erro ao converter resposta da IA em JSON. Resposta recebida: ${raw}`);
  }
} else if (typeof raw === 'object') {
  data = raw;
} else {
  throw new Error('Formato inesperado de resposta da IA.');
}

// Garantir array de pendências
if (!Array.isArray(data.pendencias_identificadas)) {
  data.pendencias_identificadas = data.pendencias_identificadas
    ? [String(data.pendencias_identificadas)]
    : [];
}

// Normalização básica
return [
  {
    json: {
      obra_codigo: data.obra_codigo ?? input.obra_codigo ?? null,
      tipo_documento: data.tipo_documento ?? null,
      categoria: data.categoria ?? null,
      data_documento: data.data_documento ?? null,
      responsavel: data.responsavel ?? input.responsavel ?? null,
      assunto: data.assunto ?? null,
      descricao_resumida: data.descricao_resumida ?? null,
      prioridade: data.prioridade ?? 'NORMAL',
      status: data.status ?? 'PENDENTE_REVISAO',
      pendencias_identificadas: data.pendencias_identificadas,
      possui_pendencias: data.pendencias_identificadas.length > 0,
      nome_original: input.nome_original ?? null,
      nome_padronizado: data.nome_padronizado ?? null,
      origem: input.origem ?? 'WEBHOOK',
      acao_recomendada: data.acao_recomendada ?? null
    }
  }
];

const input = $input.first().json;

const mensagem = (input.mensagem || '').toLowerCase();

let tipo_documento = 'OUTROS';
let categoria = 'ADMINISTRATIVO';
let prioridade = 'NORMAL';
let status = 'VALIDO';
let pendencias = [];

if (mensagem.includes('relatório diário') || mensagem.includes('relatorio diario')) {
  tipo_documento = 'RELATORIO_DIARIO';
  categoria = 'EXECUCAO';
}

if (mensagem.includes('não foram enviadas fotos') || mensagem.includes('nao foram enviadas fotos')) {
  status = 'INCOMPLETO';
  pendencias.push('Não foram enviadas fotos da execução.');
}

const dataMatch = input.mensagem.match(/(\d{2})\/(\d{2})\/(\d{4})/);
const data_documento = dataMatch
  ? `${dataMatch[3]}-${dataMatch[2]}-${dataMatch[1]}`
  : null;

const responsavel = (input.responsavel || '').toUpperCase();
const obra_codigo = input.obra_codigo || null;

return [
  {
    json: {
      output: JSON.stringify({
        obra_codigo,
        tipo_documento,
        categoria,
        data_documento,
        responsavel,
        assunto: 'Relatório diário da obra Caio',
        descricao_resumida: input.mensagem,
        prioridade,
        status,
        pendencias_identificadas: pendencias,
        nome_padronizado: `${obra_codigo}_${data_documento || 'SEM-DATA'}_${tipo_documento}_${responsavel || 'SEM-RESPONSAVEL'}.pdf`,
        acao_recomendada: pendencias.length > 0
          ? 'Arquivar como documento incompleto e solicitar complementação.'
          : 'Arquivar documento.'
      })
    }
  }
];

let randomUUID;

try {
  randomUUID = require('crypto').randomUUID;
} catch (error) {
  randomUUID = null;
}

function cleanText(value) {
  if (value === undefined || value === null) return null;
  return String(value).replace(/^=/, '').trim();
}

function fallbackUUID() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

const item = $input.first().json;

const id_documento = item.id_documento || (
  randomUUID ? randomUUID() : fallbackUUID()
);

const data_processamento = new Date().toISOString();

let pendencias = item.pendencias_identificadas;

if (!Array.isArray(pendencias)) {
  pendencias = pendencias ? [String(pendencias)] : [];
}

const possui_pendencias = pendencias.length > 0;

const executionId =
  typeof $execution !== 'undefined' && $execution?.id
    ? String($execution.id)
    : null;

const workflowName =
  typeof $workflow !== 'undefined' && $workflow?.name
    ? String($workflow.name)
    : 'Agente de Triagem Documental';

const payloadOriginal = {
  entrada: {
    obra_codigo: item.obra_codigo ?? null,
    responsavel: item.responsavel ?? null,
    mensagem: item.mensagem ?? null,
    origem: item.origem ?? null,
    nome_original: item.nome_original ?? null,
    data_recebimento: item.data_recebimento ?? null
  },
  classificacao: {
    tipo_documento: item.tipo_documento ?? null,
    categoria: item.categoria ?? null,
    data_documento: item.data_documento ?? null,
    assunto: item.assunto ?? null,
    descricao_resumida: item.descricao_resumida ?? null,
    prioridade: item.prioridade ?? null,
    status: item.status ?? null,
    pendencias_identificadas: pendencias,
    nome_padronizado: item.nome_padronizado ?? null,
    acao_recomendada: item.acao_recomendada ?? null
  }
};

return [
  {
    json: {
      ...item,

      id_documento,
      data_processamento,

      pendencias_identificadas: JSON.stringify(pendencias),
      possui_pendencias,

      payload_original: JSON.stringify(payloadOriginal),

      agente_nome: 'Agente de Triagem Documental',
      agente_versao: '0.1.0',
      modo_processamento: 'MOCK',

      workflow_nome: workflowName,
      workflow_versao: '0.1.0',
      n8n_execution_id: executionId,

      data_documento: item.data_documento || null
    }
  }
];

const atual = $input.first().json;

// Busca a mensagem original diretamente do nó inicial normalizado
const base = $items("SET_DADOS_BASICOS_AGENTE_01")[0].json;

function cleanText(value) {
  if (value === undefined || value === null) return '';
  return String(value).replace(/^=/, '').trim();
}

function extractDateBR(text) {
  const match = String(text || '').match(/(\d{2})\/(\d{2})\/(\d{4})/);

  if (!match) return null;

  const [, dd, mm, yyyy] = match;
  return `${yyyy}-${mm}-${dd}`;
}

const mensagem =
  cleanText(base.mensagem) ||
  cleanText(base.body?.mensagem) ||
  cleanText(atual.mensagem) ||
  cleanText(atual.descricao_resumida) ||
  cleanText(atual.assunto) ||
  'Relatório diário recebido pela triagem documental.';

const texto = mensagem.toLowerCase();

const dataRdo =
  extractDateBR(mensagem) ||
  cleanText(base.data_rdo) ||
  cleanText(base.data_documento) ||
  cleanText(atual.data_documento) ||
  new Date().toISOString().slice(0, 10);

const pendencias = [];

if (
  texto.includes('não foram enviadas fotos') ||
  texto.includes('nao foram enviadas fotos') ||
  texto.includes('sem fotos')
) {
  pendencias.push('Não foram enviadas fotos da execução.');
}

if (
  texto.includes('necessário confirmar') ||
  texto.includes('necessario confirmar') ||
  texto.includes('conferir')
) {
  pendencias.push('Conferir informações pendentes mencionadas no relatório.');
}

return [
  {
    json: {
      obra_codigo: cleanText(base.obra_codigo || atual.obra_codigo) || 'OBRA-001',
      data_rdo: dataRdo,
      responsavel: cleanText(base.responsavel || atual.responsavel) || 'Responsável não informado',

      clima: null,
      condicoes_canteiro: 'Não informado.',

      atividades: mensagem,
      mao_de_obra: null,
      equipamentos: null,
      materiais: null,

      ocorrencias: pendencias.length > 0 ? pendencias.join('; ') : null,
      pendencias: pendencias.length > 0 ? pendencias.join('; ') : null,

      origem: 'AGENTE_01_TRIAGEM_DOCUMENTAL',
      tipo_documento_origem: cleanText(atual.tipo_documento) || 'RELATORIO_DIARIO'
    }
  }
];

const respostaAgente02 = $input.first().json;

function cleanText(value) {
  if (value === undefined || value === null) return null;
  return String(value).replace(/^=/, '').trim();
}

function parseBoolean(value) {
  if (value === true) return true;
  if (value === false) return false;

  if (value === undefined || value === null || value === '') return null;

  const text = String(value).trim().toLowerCase();

  if (['true', 't', '1', 'sim', 'yes'].includes(text)) return true;
  if (['false', 'f', '0', 'nao', 'não', 'no'].includes(text)) return false;

  return null;
}

return [
  {
    json: {
      status: "documento_processado",
      obra_codigo: cleanText(respostaAgente02.obra_codigo),
      tipo_documento: "RELATORIO_DIARIO",
      acionou_agente_02: true,

      agente_02_status: respostaAgente02.status || null,
      data_rdo: respostaAgente02.data_rdo || null,
      status_rdo: respostaAgente02.status_rdo || null,
      possui_pendencias: parseBoolean(respostaAgente02.possui_pendencias),
      agente_03_acionado: parseBoolean(respostaAgente02.agente_03_acionado),

      mensagem: "Documento processado pela triagem documental e encaminhado ao Agente 02.",
      resposta_agente_02: respostaAgente02
    }
  }
];
